      let collected = <Test as Config>::AssetOps::balance(&sink, native);
      let owner = fixture.owner;
      assert_eq!(
        Pallet::<Test>::close_actor(RawOrigin::Signed(owner).into(), actor_id),
        Err(Error::<Test>::ImmutableActor.into())
      );
