      assert!(ServiceNodes::<Test>::contains_key(actor_id));
      assert_eq!(
        <Test as Config>::AssetOps::balance(&sink, native),
        collected
      );
      let (state, admission) = consume_zero_step_opening::<Test>(actor_id);
